export interface CohortsClient {
    /**
     * Add persons to a static cohort by their UUIDs. Only works for static cohorts (is_static: true).
     *
     * Intended for small, ad-hoc additions — pass at most ~20 person UUIDs per call. To build or grow a static cohort from a larger set, do NOT loop this tool over many UUIDs; instead create the cohort from a query ('cohorts-create' with 'is_static: true' and a 'query'), or add to an existing static cohort by setting a 'query' on it via 'cohorts-partial-update'. The server then runs the query and inserts every matching person in a single call, with no row limit.
     *
     * @mcpTool cohorts-add-persons-to-static-cohort-partial-update
     *
     * @requiredScopes cohort:write
     */
    cohortsAddPersonsToStaticCohortPartialUpdate(
        input: CohortsCohortsAddPersonsToStaticCohortPartialUpdateInput,
        options?: RequestOptions
    ): Promise<CohortsCohortsAddPersonsToStaticCohortPartialUpdateOutput>
    /**
     * Create a cohort (a saved group of persons). Two kinds:
     *
     * - Dynamic cohort (default): provide 'filters' with AND/OR groups of property conditions (person properties, behavioral filters, or cohort references). Membership is recalculated automatically.
     * - Static cohort ('is_static: true'): a fixed snapshot of persons. PREFER populating it from a 'query' (see below) — the server runs the query and inserts every matching person in a single call, with no row limit. Only use 'cohorts-add-persons-to-static-cohort-partial-update' for tiny, ad-hoc additions (up to ~20 people).
     *
     * Populate a static cohort from a query by setting BOTH 'is_static: true' and 'query'. 'query' accepts a HogQLQuery (raw SQL) or an ActorsQuery (the actors behind a product-analytics insight such as trends or funnels). The query MUST expose the person identifier under one of these column names, checked in this order: 'person_id', 'actor_id', 'id', or 'distinct_id'. Selecting from the 'events' or 'persons' tables resolves the actor automatically. If none of those columns is present the call fails with "Could not find a person_id, actor_id, id, or distinct_id column in the query".
     *
     * ALWAYS validate the query before saving it: run a HogQLQuery through the 'execute-sql' tool, and an ActorsQuery through its matching 'query-*-actors' tool (e.g. 'query-trends-actors', 'query-lifecycle-actors'). Only pass a 'query' that returned successfully — this catches column-name and syntax errors before they fail cohort population.
     *
     * Example — from SQL (HogQLQuery), alias the id column as person_id:
     * {"name": "Power users", "is_static": true, "query": {"kind": "HogQLQuery", "query": "SELECT person_id FROM events WHERE event = '$pageview' GROUP BY person_id HAVING count() > 100"}}
     *
     * Example — from a product-analytics trends insight (ActorsQuery):
     * {"name": "Viewed pricing last 7d", "is_static": true, "query": {"kind": "ActorsQuery", "source": {"kind": "InsightActorsQuery", "source": {"kind": "TrendsQuery", "series": [{"kind": "EventsNode", "event": "$pageview"}], "dateRange": {"date_from": "-7d"}}}}}
     *
     * @mcpTool cohorts-create
     *
     * @requiredScopes cohort:write
     */
    cohortsCreate(input: CohortsCohortsCreateInput, options?: RequestOptions): Promise<CohortsCohortsCreateOutput>
    /**
     * Update an existing cohort's name, description, or filters. Changing filters on a dynamic cohort triggers recalculation. To soft-delete a cohort, set 'deleted: true'.
     *
     * To add more people to an existing STATIC cohort in bulk, set a 'query' (HogQLQuery or ActorsQuery) on it — the server runs the query and inserts every newly matched person (existing members are skipped), with no row limit. The query must expose the person id under one of these column names, checked in order: 'person_id', 'actor_id', 'id', or 'distinct_id' (selecting from the 'events' or 'persons' tables resolves the actor automatically). Validate the query before saving it — run a HogQLQuery through 'execute-sql' and an ActorsQuery through its matching 'query-*-actors' tool (e.g. 'query-trends-actors') — and only save one that returned successfully. Prefer this over 'cohorts-add-persons-to-static-cohort-partial-update' for anything beyond a handful (~20) of people.
     *
     * @mcpTool cohorts-partial-update
     *
     * @requiredScopes cohort:write
     */
    cohortsPartialUpdate(
        input: CohortsCohortsPartialUpdateInput,
        options?: RequestOptions
    ): Promise<CohortsCohortsPartialUpdateOutput>
    /**
     * Remove a person from a static cohort by their UUID. Only works for static cohorts (is_static: true). The person must exist in the project. Idempotent: removing a person who exists but is not a member of the cohort succeeds silently.
     *
     * @mcpTool cohorts-rm-person-from-static-cohort-partial-update
     *
     * @requiredScopes cohort:write
     */
    cohortsRmPersonFromStaticCohortPartialUpdate(
        input: CohortsCohortsRmPersonFromStaticCohortPartialUpdateInput,
        options?: RequestOptions
    ): Promise<CohortsCohortsRmPersonFromStaticCohortPartialUpdateOutput>
    /**
     * Get a specific cohort by ID. Returns the cohort name, description, filters (for dynamic cohorts), count of matching users, and calculation status.
     *
     * @mcpTool cohorts-retrieve
     *
     * @requiredScopes cohort:read
     */
    get(input: CohortsGetInput, options?: RequestOptions): Promise<CohortsGetOutput>
    /**
     * List all cohorts in the project. Returns a summary of each cohort including  id, name, description, count (person count), is_static (cohort type), and created_at timestamp. To find a cohort by name, pass 'search' rather than listing everything and filtering client-side — it matches the cohort name with fuzzy trigram search (tolerates typos and partial words) and orders exact matches first. Use 'cohorts-retrieve' with the cohort ID to get full details including filters, calculation status,
     * and query definition.
     *
     * @mcpTool cohorts-list
     *
     * @requiredScopes cohort:read
     */
    list(input: CohortsListInput, options?: RequestOptions): Promise<CohortsListOutput>
}
export function createCohortsClient(runtime: Runtime): CohortsClient {
    return {
        cohortsAddPersonsToStaticCohortPartialUpdate: (input, options) =>
            runtime.executeTool<CohortsCohortsAddPersonsToStaticCohortPartialUpdateOutput>(
                'cohorts-add-persons-to-static-cohort-partial-update',
                input,
                options
            ),
        cohortsCreate: (input, options) =>
            runtime.executeTool<CohortsCohortsCreateOutput>('cohorts-create', input, options),
        cohortsPartialUpdate: (input, options) =>
            runtime.executeTool<CohortsCohortsPartialUpdateOutput>('cohorts-partial-update', input, options),
        cohortsRmPersonFromStaticCohortPartialUpdate: (input, options) =>
            runtime.executeTool<CohortsCohortsRmPersonFromStaticCohortPartialUpdateOutput>(
                'cohorts-rm-person-from-static-cohort-partial-update',
                input,
                options
            ),
        get: (input, options) => runtime.execute<CohortsGetOutput>(getDefinition, input, options),
        list: (input, options) => runtime.execute<CohortsListOutput>(listDefinition, input, options),
    }
}
